const e=["Dieu","Aube","Religion"],n="Déesse de l’Aube",t=["Cione représente l'Aube.","Elle symbolise les commencements, les premiers espoirs et les moments où quelque chose apparaît après une période d'obscurité.","Elle n'est pas la déesse de la Lumière elle-même.","L'Aube est un instant particulier : elle est le passage entre deux états.","La nuit n'a pas encore complètement disparu.","Le jour n'est pas encore arrivé.","C'est précisément dans cet entre-deux que Cione trouve sa place."],s=[{label:"Domaines",value:"Aube"},{label:"Symboles",value:"Un soleil levant, une ligne d'horizon, une fleur qui s'ouvre, une flamme, un oiseau prenant son envol"}],o=[{title:"L'Aube",title_border:"#e8553d",type:"text",content:["Pour les fidèles de Cione, l'Aube représente la possibilité de recommencer.","Une nouvelle journée.","Une nouvelle route.","Une nouvelle chance.","Mais Cione ne promet pas que chaque commencement sera heureux.","L'Aube annonce simplement que la nuit est terminée.","Ce qui vient ensuite appartient aux mortels."]},{title:"Le culte de Cione",title_border:"#c2660a",type:"text",content:["Les temples de Cione sont souvent orientés vers l'est afin que les premiers rayons du soleil puissent atteindre leurs autels.","Ses fidèles se réunissent parfois avant le lever du soleil pour assister ensemble à l'apparition de la lumière.","Les cérémonies accompagnent notamment :"]},{title:"",type:"list",content:["Les nouveaux départs","Les voyages","Les naissances","Les reconstructions","Les célébrations après une victoire","Les personnes cherchant à tourner une page de leur vie"]},{title:"",type:"text",content:"Les prêtres de Cione sont souvent associés à l'accueil des voyageurs et aux cérémonies de renouveau."},{title:"Cione et Cirana",title_border:"#6f9fd8",type:"text",content:["Cione est traditionnellement associée à Cirana, déesse du Crépuscule.","Elles ne sont pas considérées comme ennemies.","L'une annonce la fin de la nuit.","L'autre annonce la fin du jour.","Certaines traditions les décrivent comme deux sœurs.","D'autres comme deux aspects d'une même divinité.","Aucune interprétation n'est universelle.","Ce qui demeure commun à leurs cultes est l'idée que tout commencement implique une fin, et que toute fin peut devenir un commencement."]},{title:"Cione et Fauscht",title_border:"#e8553d",type:"text",content:["Cione entretient également un lien symbolique avec Fauscht.","L'Aube représente le début d'une journée.","La Mort représente la fin d'une vie.","Mais les deux ne sont pas nécessairement opposés.","Dans certaines traditions funéraires, une nouvelle journée est considérée comme une promesse faite aux vivants : continuer malgré ceux qui sont partis."]},{title:"Symboles",title_border:"#c2660a",type:"text",content:"Cione est généralement représentée par :"},{title:"",type:"list",content:["Un soleil levant","Une ligne d'horizon","Une fleur qui s'ouvre","Une flamme","Un oiseau prenant son envol"]},{title:"",type:"text",content:"Ses couleurs varient énormément selon les régions, mais les représentations utilisent souvent des tons rappelant le ciel juste avant le lever du soleil."},{title:"Aujourd'hui",title_border:"#6f9fd8",type:"text",content:["Cione est une divinité discrète mais largement connue.","Son culte possède rarement une influence politique importante.","Elle accompagne surtout les moments personnels.","Un voyageur quittant sa maison.","Un enfant venant au monde.","Une communauté reconstruisant son village.","Un survivant décidant de recommencer.","Dans tous ces moments, les fidèles de Cione regardent vers l'est.","Car l'Aube ne promet rien.","Elle rappelle seulement qu'une nouvelle journée est possible."]}],i=["Les Dieux","Cirana","Fauscht","Metona","L’Aube","Le Crépuscule"],r={tags:e,surname:n,presentation:t,infos:s,sections:o,related:i};export{r as default,s as infos,t as presentation,i as related,o as sections,n as surname,e as tags};
